package org.telegram.messenger; import java.util.*; public final class AndroidUtilities {public static final List<Runnable> pending=new ArrayList<>();public static boolean immediate;public static void runOnUIThread(Runnable r){if(immediate)r.run();else pending.add(r);} public static int dp(float x){return (int)x;} public static void drain(){while(!pending.isEmpty())pending.remove(0).run();}}
